// Absolutize an origin media playlist's RELATIVE URIs against the origin playlist URL.
//
// When the SSAI wraps a real EXTERNAL ChannelForge origin, the stitched manifest is served from
// the SSAI host — so an origin's relative content URI like `index0.ts` would otherwise resolve
// against the SSAI (`…/v1/hls/{token}/{channel}/index0.ts`) and 404. Rewriting content URIs to
// absolute origin URLs (`https://forge…/hls/{uuid}/index0.ts`) lets the player pull content
// straight from ChannelForge, while ad segments the stitcher inserts stay absolute SSAI paths.
// For the co-located fixture origin (relative URIs that already resolve) this is a harmless no-op
// difference, so it's safe to apply unconditionally.

function absolutize(uri: string, base: URL): string {
  const t = uri.trim();
  if (!t || /^https?:\/\//i.test(t)) return uri; // already absolute
  try {
    return new URL(t, base).toString();
  } catch {
    return uri;
  }
}

export function absolutizeManifest(body: string, originUrl: string): string {
  let base: URL;
  try {
    base = new URL(originUrl);
  } catch {
    return body; // non-absolute origin (e.g. fixture http://host/...) still parses; bad input → passthrough
  }
  return body
    .split("\n")
    .map((line) => {
      const t = line.trim();
      if (!t) return line;
      // A bare segment URI line (not a tag).
      if (!t.startsWith("#")) return absolutize(line, base);
      // Tags that carry a URI="..." attribute (EXT-X-MAP, EXT-X-KEY, …).
      return line.replace(/URI="([^"]+)"/g, (_m, u) => `URI="${absolutize(u, base)}"`);
    })
    .join("\n");
}
